package local.hydratest;
import java.util.*;import java.nio.file.*;
import net.minecraft.core.*;import net.minecraft.core.registries.*;import net.minecraft.resources.Identifier;import net.minecraft.server.level.*;import net.minecraft.world.entity.*;import net.minecraft.world.entity.ai.attributes.Attributes;import net.minecraft.world.phys.*;
import net.neoforged.fml.common.Mod;import net.neoforged.neoforge.common.NeoForge;import net.neoforged.neoforge.event.server.ServerStartedEvent;
import net.spell_engine.api.spell.*;import net.spell_engine.api.spell.registry.SpellRegistry;import net.spell_engine.api.spell.summon.*;import net.spell_engine.entity.SummonedEntity;import net.spell_engine.internals.*;import net.spell_engine.internals.casting.*;import net.spell_power.api.*;
@Mod("phase_two_probe") public class HydraProbe {
 ServerLevel w;ServerPlayer owner;SummonedEntity hydra;int failures;List<String> checks=new ArrayList<>();
 public HydraProbe(){NeoForge.EVENT_BUS.addListener(this::start);}
 void check(boolean ok,String label){checks.add((ok?"PASS ":"FAIL ")+label);if(!ok)failures++;}
 Holder<Spell> spell(String id){return SpellRegistry.from(w).get(Identifier.parse(id)).orElseThrow();}
 LivingEntity enemy(double x,double z){var e=EntityTypes.CREEPER.create(w,EntitySpawnReason.COMMAND);e.setPos(x,80,z);e.setNoAi(true);e.setNoGravity(true);e.getAttribute(Attributes.MAX_HEALTH).setBaseValue(1000);e.setHealth(1000);w.addFreshEntity(e);return e;}
 SummonedEntity summon(boolean ancient,double x){var h=spell("wizards:fire_hydra");var def=h.value().impacts.stream().filter(i->i.action.type==Spell.Impact.Action.Type.SUMMON).findFirst().orElseThrow().action.summon;var scaling=ancient?spell("skill_tree_rpgs:fire_tier_4_spell_2_modifier_2").value().modifiers.getFirst().summon_attribute_scaling:new AttributeScaling();var e=(SummonedEntity)BuiltInRegistries.ENTITY_TYPE.getValue(Identifier.parse("wizards:fire_hydra")).create(w,EntitySpawnReason.COMMAND);e.setPos(x,80,0);e.onSummonedBySpell(new SpellSummoned.Args(owner,h,def.behaviour,scaling,new SpellExecution.ImpactContext().power(new SpellPower.Result(SpellSchools.FIRE,40,0,1))));e.getAttribute(BuiltInRegistries.ATTRIBUTE.get(Identifier.parse("spell_power:fire")).orElseThrow()).setBaseValue(40);e.setNoAi(true);e.setNoGravity(true);w.addFreshEntity(e);return e;}
 void start(ServerStartedEvent event){w=event.getServer().overworld();for(int x=-3;x<=3;x++)for(int z=-3;z<=3;z++)w.setChunkForced(x,z,true);((net.spell_engine.utils.WorldScheduler)w).schedule(40,()->run(event));}
 void run(ServerStartedEvent event){try{
  owner=net.neoforged.neoforge.common.util.FakePlayerFactory.getMinecraft(w);owner.connection.markClientLoaded();owner.setPos(-30,80,-30);owner.getAttribute(BuiltInRegistries.ATTRIBUTE.get(Identifier.parse("spell_power:critical_chance")).orElseThrow()).setBaseValue(0);
  for(int x=-40;x<=40;x++)for(int z=-25;z<=25;z++)w.setBlock(new BlockPos(x,79,z),net.minecraft.world.level.block.Blocks.STONE.defaultBlockState(),3);
  hydra=summon(true,0);check(SummonRules.ancient(hydra),"Uses actual large-Hydra summon and existing scale");check(hydra.behaviour.targeting.detection_range.value==20,"Native large-Hydra behavior also records20-block detection");
  var far=enemy(0,16);SummonRules.tick(hydra);check(hydra.getTarget()==far,"Detects and targets enemy beyond shooting range inside20");
  Vec3 before=hydra.position();for(int i=0;i<20;i++)SummonRules.tick(hydra);check(Math.abs(hydra.position().distanceTo(before)-1)<.02,"Pursuit remains one block per second");
  var breath=spell("wizards:ancient_hydra_breath");SummonRules.channel(hydra,breath);check(hydra.getSpellCastProcess()==null,"Does not channel or show fire outside shooting range");check(far.getHealth()==1000,"Outside-range pursuit deals no breath damage");far.discard();hydra.setPos(0,80,0);
  var edge=enemy(0,20);SummonRules.tick(hydra);check(hydra.getTarget()==edge,"Detection includes20-block boundary");edge.discard();hydra.setPos(0,80,0);
  var outside=enemy(0,20.1);SummonRules.tick(hydra);check(hydra.getTarget()==null,"Does not acquire beyond20 blocks");outside.discard();
  var closer=enemy(0,-10);var shootable=enemy(0,11);hydra.setYBodyRot(0);hydra.setYRot(0);hydra.setPos(0,80,0);SummonRules.tick(hydra);check(hydra.getTarget()==shootable,"Shootable enemy prioritized over closer out-of-fire-volume enemy");closer.discard();shootable.discard();
  var near=enemy(0,8);var farther=enemy(0,10);hydra.setPos(0,80,0);SummonRules.tick(hydra);check(hydra.getTarget()==near,"Chooses closest of multiple enemies in firing range");check(hydra.position().distanceToSqr(Vec3.ZERO.add(0,80,0))<.0001,"Stops walking while target is in firing range");
  SummonRules.orient(hydra,near);hydra.declareCastProcess(new SpellCast.Process(hydra,breath,null,1,100,w.getGameTime()-2));SummonRules.channel(hydra,breath);check(near.getHealth()<1000,"Native breath actually damages an in-range enemy");check(farther.getHealth()<1000,"Existing breath cone still hits eligible in-range bystanders");
  near.setPos(0,80,18);farther.discard();SummonRules.tick(hydra);SummonRules.channel(hydra,breath);check(hydra.getTarget()==near&&hydra.getSpellCastProcess()==null,"Enemy leaving fire range becomes pursuit target and stops breath");near.discard();
  var occluded=enemy(0,16);for(int x=-2;x<=2;x++)for(int y=80;y<=90;y++)w.setBlock(new BlockPos(x,y,10),net.minecraft.world.level.block.Blocks.STONE.defaultBlockState(),3);hydra.setPos(0,80,0);SummonRules.tick(hydra);check(hydra.getTarget()==null,"Blocked line of sight prevents acquisition");occluded.discard();
  for(int x=-2;x<=2;x++)for(int y=80;y<=90;y++)w.setBlock(new BlockPos(x,y,10),net.minecraft.world.level.block.Blocks.AIR.defaultBlockState(),3);
  var normal=summon(false,30);var normalFar=enemy(30,16);Vec3 normalPos=normal.position();SummonRules.tick(normal);check(normal.getTarget()==null&&normal.position().equals(normalPos),"Ordinary Hydras keep twelve-block search and remain stationary");check(!SummonRules.channel(normal,breath),"Ordinary Hydra native action path unchanged");
 }catch(Throwable t){t.printStackTrace();check(false,"Exception "+t);}finally{try{Files.write(Path.of("phase-two-checks.txt"),checks);Files.writeString(Path.of("phase-two-result.txt"),(failures==0?"PASS ":"FAIL ")+checks.size()+" checks; failures="+failures+"\n");}catch(Exception ignored){}event.getServer().halt(false);}}
}
